import sqlite3

import pandas as pd

from src.config import DATABASE_PATH, DOCS_DIR


QA_REPORT = DOCS_DIR / "qa_report.md"


def run_qa() -> pd.DataFrame:
    if not DATABASE_PATH.exists():
        raise FileNotFoundError(f"Database not found: {DATABASE_PATH}")

    with sqlite3.connect(DATABASE_PATH) as connection:
        results = pd.read_sql_query(
            "SELECT check_name, severity, issue_count FROM qa_summary ORDER BY severity, check_name",
            connection,
        )

    lines = [
        "# Data QA report",
        "",
        "Generated by `python -m src.run_qa` after the SQLite build.",
        "",
        "| Check | Severity | Issues | Result |",
        "|---|---|---:|---|",
    ]
    for row in results.itertuples(index=False):
        if row.severity == "error":
            result = "PASS" if row.issue_count == 0 else "FAIL"
        else:
            result = "REVIEW"
        lines.append(
            f"| `{row.check_name}` | {row.severity} | {row.issue_count:,} | {result} |"
        )
    lines.extend(
        [
            "",
            "Negative profit is retained as a real business condition for analysis; it is not automatically removed as a data-quality error.",
            "",
        ]
    )
    QA_REPORT.write_text("\n".join(lines), encoding="utf-8")

    failures = results.loc[
        (results["severity"] == "error") & (results["issue_count"] > 0)
    ]
    if not failures.empty:
        raise RuntimeError(f"QA failures:\n{failures.to_string(index=False)}")

    print(results.to_string(index=False))
    print(f"Wrote {QA_REPORT}")
    return results


if __name__ == "__main__":
    run_qa()
